func (r *NoOpParcelRepository) GetOne(_ context.Context, _ types.IdentityUUID, _ *ParcelGetOptions) (*types.Parcel, error) {
	return nil, ErrNotFound
}

func (r *NoOpParcelRepository) GetManyByIDs(_ context.Context, _ []types.IdentityUUID) (map[types.IdentityUUID]*types.Parcel, error) {
	return map[types.IdentityUUID]*types.Parcel{}, nil
}

func (r *NoOpParcelRepository) FindOne(_ context.Context, _ *ParcelFilter, _ *ParcelFindOptions) (*types.Parcel, error) {
	return nil, ErrNotFound
}

func (r *NoOpParcelRepository) FindMany(_ context.Context, _ *ParcelFilter, _ *ParcelFindOptions) ([]*types.Parcel, int, error) {
	return []*types.Parcel{}, 0, nil
}

func (r *NoOpParcelRepository) FindPage(_ context.Context, _ *ParcelFilter, _ *ParcelPageOptions) (*ParcelPage, error) {
	return &ParcelPage{Rows: []*types.Parcel{}}, nil
}

func (r *NoOpParcelRepository) CreateOne(_ context.Context, input *types.Parcel) (*types.Parcel, error) {
	return input, nil
}

func (r *NoOpParcelRepository) CreateMany(_ context.Context, inputs []*types.Parcel) ([]*types.Parcel, error) {
	if inputs == nil {
		return []*types.Parcel{}, nil
	}
	return inputs, nil
}

func (r *NoOpParcelRepository) UpsertOne(_ context.Context, input *types.Parcel, _ ParcelUniqueKey, _ *ParcelUpdate) (*types.Parcel, error) {
	return input, nil
}

func (r *NoOpParcelRepository) UpsertOneResult(_ context.Context, input *types.Parcel, _ ParcelUniqueKey, _ *ParcelUpdate, _ *UpsertOptions) (UpsertResult[*types.Parcel], error) {
	return UpsertResult[*types.Parcel]{Row: input, Status: UpsertInserted}, nil
}

func (r *NoOpParcelRepository) UpsertMany(_ context.Context, inputs []*types.Parcel, _ ParcelUniqueKey, _ ParcelFields, _ *UpsertOptions) ([]UpsertResult[*types.Parcel], error) {
	results := make([]UpsertResult[*types.Parcel], len(inputs))
	for i, input := range inputs {
		results[i] = UpsertResult[*types.Parcel]{Row: input, Status: UpsertInserted}
	}
	return results, nil
}

func (r *NoOpParcelRepository) UpdateOne(_ context.Context, _ types.IdentityUUID, _ *ParcelUpdate) (*types.Parcel, error) {
	return nil, ErrNotFound
}

func (r *NoOpParcelRepository) UpdateMany(_ context.Context, _ *ParcelFilter, _ *ParcelUpdate) (int, error) {
	return 0, nil
}

func (r *NoOpParcelRepository) DeleteOne(_ context.Context, _ types.IdentityUUID) error {
	return nil
}

func (r *NoOpParcelRepository) DeleteMany(_ context.Context, _ *ParcelFilter) (int, error) {
	return 0, nil
}

var (
	_ DatabaseInterface                   = (*Database)(nil)
	_ DatabaseInterface                   = (*NoOpDatabase)(nil)
	_ ReadOnlyDatabaseInterface           = (*Database)(nil)
	_ ReadOnlyDatabaseInterface           = (*NoOpDatabase)(nil)
	_ TxInterface                         = (*Tx)(nil)
	_ TxInterface                         = (*NoOpTx)(nil)
	_ ReadOnlyTxInterface                 = (*Tx)(nil)
	_ ReadOnlyTxInterface                 = (*NoOpTx)(nil)
	_ CourierRepositoryInterface          = (*CourierRepository)(nil)
	_ CourierRepositoryInterface          = (*NoOpCourierRepository)(nil)
	_ ReadOnlyCourierRepositoryInterface  = (*CourierRepository)(nil)
	_ ReadOnlyCourierRepositoryInterface  = (*NoOpCourierRepository)(nil)
	_ DeliveryRepositoryInterface         = (*DeliveryRepository)(nil)
	_ DeliveryRepositoryInterface         = (*NoOpDeliveryRepository)(nil)
	_ ReadOnlyDeliveryRepositoryInterface = (*DeliveryRepository)(nil)
	_ ReadOnlyDeliveryRepositoryInterface = (*NoOpDeliveryRepository)(nil)
	_ DepotRepositoryInterface            = (*DepotRepository)(nil)
	_ DepotRepositoryInterface            = (*NoOpDepotRepository)(nil)
	_ ReadOnlyDepotRepositoryInterface    = (*DepotRepository)(nil)
	_ ReadOnlyDepotRepositoryInterface    = (*NoOpDepotRepository)(nil)
	_ ParcelRepositoryInterface           = (*ParcelRepository)(nil)
	_ ParcelRepositoryInterface           = (*NoOpParcelRepository)(nil)
	_ ReadOnlyParcelRepositoryInterface   = (*ParcelRepository)(nil)
	_ ReadOnlyParcelRepositoryInterface   = (*NoOpParcelRepository)(nil)
)
